# Extend known LLM instrumentation scopes with any extra prefixes specified via environment variable.
_EXTRA_PREFIXES = os.getenv("LANGFUSE_EXTRA_LLMS_INSTRUMENTATION_SCOPE_PREFIXES")
if _EXTRA_PREFIXES:
    KNOWN_LLM_INSTRUMENTATION_SCOPE_PREFIXES = frozenset(
        KNOWN_LLM_INSTRUMENTATION_SCOPE_PREFIXES.union(
            {p.strip() for p in _EXTRA_PREFIXES.split(",") if p.strip()}
        )
    )"
