  "test_path": "tests/unit/test_span_filter_extra.py",
  "test": "import importlib
import os
from types import SimpleNamespace

import pytest


def _reload_span_filter():
    # Helper to reload the module after changing env vars
    import langfuse.span_filter as sf
    importlib.reload(sf)
    return sf


def test_extra_llm_instrumentor_enabled(monkeypatch):
    monkeypatch.setenv("LANGFUSE_EXTRA_LLMS_INSTRUMENTATION_SCOPE_PREFIXES", "my.custom.scope")
    sf = _reload_span_filter()
    span = SimpleNamespace(instrumentation_scope=SimpleNamespace(name="my.custom.scope.sub"))
    assert sf.is_known_llm_instrumentor(span) is True


def test_extra_llm_instrumentor_disabled(monkeypatch):
    monkeypatch.delenv("LANGFUSE_EXTRA_LLMS_INSTRUMENTATION_SCOPE_PREFIXES", raising=False)
    sf = _reload_span_filter()
    span = SimpleNamespace(instrumentation_scope=SimpleNamespace(name="my.custom.scope.sub"))
    assert sf.is_known_llm_instrumentor(span) is False"
}
